   "scenario":"У сайта есть версии на русском, польском и английском в папках /ru/, /pl/, /en/. Пользователи из Польши жалуются, что в выдаче им показывается русская версия. В коде страниц hreflang присутствует, но только на русской версии: она ссылается на польскую и английскую. На польской и английской версиях hreflang нет.",
   "solution":"Здесь две ошибки, и вторая серьёзнее первой. Первая: hreflang односторонний — Google учитывает только взаимные ссылки, поэтому связь между версиями фактически не установлена, и каждая версия рассматривается сама по себе. Вторая: canonical со всех версий указывает на русскую, то есть сайт прямо сообщает поисковику, что польская и английская версии — дубли русской. При таком указании они и не должны показываться в выдаче: система работает ровно так, как её настроили. Правильная конфигурация: на каждой версии canonical указывает сам на себя, и каждая версия содержит полный набор hreflang — ссылки на все три версии, включая саму себя, плюс x-default на ту версию, которая должна показываться при несовпадении языка. Коды должны быть валидными: ru, pl, en, а если нужна региональная привязка — в формате язык-РЕГИОН. Редирект по геолокации как решение предлагать не нужно: он лишает робота доступа к остальным версиям.",
