   "scenario":"Screaming Frog нашёл 1 400 URL, участвующих в редиректах. Большинство карточек товара доступны по старому адресу, который ведёт 302 на промежуточный URL, а тот — 301 на конечный со слешем. Часть старых адресов ведёт на страницы, которых больше нет, и в конце цепочки отдаётся 404.",
   "solution":"Задача распадается на три части. Первая: цепочки с рабочим концом. Их сводят к одному переходу и меняют 302 на 301, поскольку переезд постоянный. Вторая: цепочки, заканчивающиеся 404. Здесь редирект на главную не годится — это трактуется как мягкая 404. Если есть релевантная страница-замена (например, категория товара), ведут на неё; если замены нет, честнее отдавать 404 или 410 и убрать ссылки. Третья, которую часто забывают: внутренние ссылки в меню и каталоге должны вести сразу на конечные адреса. Пока они ведут на старые, редиректы продолжают срабатывать при каждом обходе и каждом клике пользователя. Задача разработчику формулируется через поведение с примерами: «сейчас URL A отдаёт 302 на B, затем 301 на C; нужно, чтобы A отдавал сразу 301 на C; проверка — один переход, код 301, конечный URL». Результат проверяется повторным краулом: вкладка Redirect Chains должна опустеть.",
