   "scenario":"Компания запускает новую услугу — аудит скорости сайта. Отдельной страницы под неё пока нет. Вам поручили собрать семантику и предложить, какие страницы создать. Сайт живой, Search Console подключён, доступ к Ahrefs есть.",
   "solution":"Порядок источников определяется их надёжностью. Search Console первый, потому что показывает фактические запросы, по которым сайт уже показывается — там могут обнаружиться смежные запросы про скорость, по которым страница технического аудита уже получает показы. Дальше расширение: подсказки поиска, связанные запросы, Keyword Planner для оценки спроса, выгрузка запросов конкурентов из Ahrefs. Всё сводится в одну таблицу с указанием источника и частотности, после чего идёт чистка: чужие бренды, нерелевантное, запросы про скорость интернета вместо скорости сайта. Интент определяется по фактической выдаче: «аудит скорости сайта заказать» — коммерческий, «как проверить скорость сайта» — информационный, и это разные страницы. Кластеризация по пересечению выдачи. Отдельный обязательный шаг в этом кейсе: проверить пересечение с существующей страницей «Технический аудит» — если выдача по новым запросам совпадает с выдачей по её запросам, отдельная страница создаст каннибализацию, и правильнее расширить существующую. На выходе таблица mapping: кластер, основной запрос, интент, целевой URL, статус «есть страница» или «нужна новая».",
