   "scenario":"По итогам сбора семантики нужна статья под информационный кластер «как проверить скорость сайта». Копирайтер не разбирается в SEO и раньше писал тексты для другой отрасли. Предыдущее ТЗ от другого специалиста было списком ключей с указанием плотности, и текст пришлось полностью переписывать.",
   "solution":"ТЗ строится вокруг задачи, а не вокруг формы. Обязательные части: целевой URL, основной запрос кластера, интент и портрет читателя, структура по заголовкам, обязательные смысловые блоки, примеры из топа, ограничения и критерии приёмки. Структуру полезно задавать вопросами читателя: чем измеряют скорость, какие инструменты есть, что означают показатели, что делать с плохим результатом — заголовки строятся под эти вопросы. Ключевые слова передаются списком с пометкой «использовать по смыслу, точные вхождения не требуются» — это снимает риск переспама у копирайтера, который привык к жёстким требованиям. Объём указывается ориентировочно, с оговоркой, что он следует из задачи: «примерно столько, сколько нужно, чтобы закрыть четыре вопроса выше; для ориентира страницы из топа занимают 900-1400 слов». Критерии приёмки формулируются проверяемо: все четыре вопроса раскрыты, каждый инструмент назван с указанием, что именно он показывает, нет обещаний и оценочных утверждений без источника, текст понятен человеку без технического бэкграунда. Отдельным блоком — чего делать нельзя: вода во вступлении, перечисление синонимов ради объёма, чужие факты без ссылки на источник.",
