   "scenario":"Вы обнаружили, что на всех страницах каталога отсутствует тег canonical, а страницы доступны одновременно со слешем и без него, а также с параметром сортировки. Нужно поставить задачу разработчику. Разработчик занят и уже возвращал задачи от маркетинга с комментарием «непонятно, что именно нужно».",
   "solution":"Задача формулируется так, чтобы её можно было выполнить и проверить, не задавая уточняющих вопросов. Текущее поведение с примерами: «/catalog/shoes и /catalog/shoes/ отдают 200 и одинаковое содержимое; /catalog/shoes?sort=price тоже отдаёт 200; тега link rel=canonical в head нет ни на одной из версий». Требуемое поведение через результат: «на всех страницах каталога в head присутствует link rel=canonical с абсолютным URL; для страницы без параметров он указывает сам на себя в канонической форме (со слешем); для страниц с параметрами сортировки — на версию без параметров; для страниц пагинации — сама на себя». Критерий приёмки проверяемый: «открыть исходный код любой страницы каталога и найти ровно один тег canonical с ожидаемым значением; проверить три приложенных примера». Зачем — одной фразой на языке результата: «сейчас поисковик видит несколько адресов с одинаковым содержимым и сам выбирает, какой показывать; из-за этого в выдачу может попасть версия с параметром сортировки». Приоритет указывается явно и честно. После выката проверка выполняется самостоятельно на приложенных примерах, и задача закрывается с подтверждением, а не молча.",
