   "level":2,
   "model_answer_en":"Crawling means the search engine downloads the page. Indexing means it decides to store the page and show it in results. Crawling does not guarantee indexing: a page can be crawled and then dropped, for example if it duplicates another page or the canonical points somewhere else.",
   "model_answer_ru":"Обход означает, что поисковая система скачала страницу. Индексация — что она решила хранить её и показывать в выдаче. Обход не гарантирует индексацию: страницу могут обойти и не взять, например если она дублирует другую или canonical указывает в другое место.",
   "prompt_en":"What is the difference between crawling and indexing?",
