   "level":2,
   "model_answer_en":"First I'd check whether the drop is real: tracking can break and show a fake drop. Then I'd compare the same period a year ago to rule out seasonality. Next I'd look at Search Console — impressions, indexed pages and any manual actions. After that I'd check what changed on the site: releases, redirects and the robots file. Only then I'd think about an algorithm update.",
   "model_answer_ru":"Сначала проверил(а) бы, настоящее ли падение: аналитика могла сломаться и показать ложное. Потом сравнил(а) бы с тем же периодом год назад, чтобы исключить сезонность. Дальше — Search Console: показы, индексация, санкции. Затем изменения на сайте: релизы, редиректы, robots. И только потом версия про апдейт алгоритма.",
   "prompt_en":"Organic traffic dropped by 30% last week. How do you investigate?",
