   "model_answer_ru":"Сначала объясняю эффект: шаблон стоит примерно на четырёх тысячах страниц, и у всех одинаковый title, поэтому поиск выбирает одну и игнорирует остальные. Это около четверти посадочных. Правка — одно изменение в шаблоне, трудозатраты маленькие, приоритет высокий. И сразу говорю, как мы проверим результат.",
   "prompt_en":"How do you explain to a developer why a technical fix matters for SEO?",
