   "estimated_minutes":25,
   "example":"Нужно убрать из выдачи страницу /search?q=. Правильно: разрешить обход и поставить noindex — страница остаётся доступной людям. Неправильно: закрыть в robots.txt, тогда робот не прочитает директиву и страница может остаться в выдаче без описания. А если бы раздел удалили совсем, корректным ответом был бы код 410.",
   "id":"lesson-robots-sitemap-canonical",
