   "example":"У страницы показы выросли вдвое, клики не изменились. Смотрим запросы: добавились новые, по ним средняя позиция 20+. Значит охват вырос, но до кликабельных мест ещё далеко — правильный вывод, а не «CTR упал, надо менять description».",
