   "short_answer":"Показы, клики, CTR и среднюю позицию, всегда в сравнении периодов. Показы говорят об охвате, клики — о результате, CTR — о качестве сниппета и позиции, средняя позиция — вспомогательная метрика. Разрезаю данные по запросам и страницам: так видно, растёт ли охват, проседает ли конкретная страница, или проблема в сниппете. Отдельно проверяю, не изменилась ли сезонность.",
