   "short_answer":"Это три метрики пользовательского опыта: LCP — скорость появления основного контента, INP — отзывчивость на действия, CLS — стабильность вёрстки. Они учитываются как часть оценки страницы, но не заменяют релевантность: страница, которая хуже отвечает на запрос, не обгонит конкурента за счёт скорости. Смотрю в первую очередь полевые данные реальных пользователей, а не лабораторный балл.",
