   "estimated_minutes":12,
   "example":"У конкурента 400 ссылающихся доменов, у нас 90. В разрыве 250 доменов, но после фильтра по теме и живому трафику остаётся 30, из них 12 — отраслевые обзоры, куда мы объективно можем попасть. Это и есть план, а не 250 покупок.",
