   "short_answer":"Сначала проверяю сам разрыв: сравниваю по ссылающимся доменам, а не по числу ссылок, и смотрю, на какие страницы конкурента они ведут. Потом фильтрую разрыв по теме, живому трафику и достижимости — обычно из сотен доменов остаются десятки. Дальше предлагаю план: аутрич по отобранным площадкам и один-два повода для digital PR. Про закупку говорю прямо: это описано в спам-политиках как ссылочная схема, такие ссылки обесцениваются, а при масштабе можно получить ручные меры. И называю, чем буду мерить результат: прирост доноров на целевые страницы и динамика видимости, а не число купленных ссылок.",
