   "estimated_minutes":12,
   "example":"Одна и та же страница обзора для двух стран отличается не переводом, а списком доступных операторов, валютой, обязательными предупреждениями и требованиями к раскрытию условий. Технически это разные страницы с корректными парами hreflang, а не переведённая копия.",
   "id":"lesson-igaming-context",
   "interview_question":"Почему вы хотите работать в iGaming?",
   "key_points":[
    "Коммерческая выдача ниши состоит в основном из партнёрских обзоров и рейтингов, поэтому тип страницы планируется в этой системе координат: рейтинг конкурирует с рейтингом.",
    "Рынков несколько, и локализация — это не перевод: меняются доступность услуги, местные правила, валюта, способы оплаты и обязательные оговорки.",
    "Тема относится к YMYL: нужны авторство, актуальность, источники и прозрачные условия. Общий текст «ни о чём» здесь не работает.",
    "Конкуренция за ссылки высокая, и давление в сторону закупки объёма — обычная рабочая ситуация. Умение объяснить риск важнее умения найти площадку.",
    "Брендовые и небрендовые запросы разделяют в отчётности: бренд растёт от рекламы, а не от вашей работы, и смешивать их — значит завышать собственный результат.",
    "Часть рекламных каналов в нише ограничена, поэтому вес органики и её доля в привлечении выше обычного — это и делает позицию заметной внутри компании."
   ],
   "practice_task":"Найдите три партнёрских сайта ниши в выдаче по одному коммерческому запросу. Выпишите, чем отличаются их страницы: тип, структура, наличие автора и даты, какие оговорки присутствуют. Сформулируйте, что из этого вы бы повторили.",
   "related_question_ids":[],
   "related_term_ids":[
    "t-igaming-affiliate",
    "t-ymyl",
    "t-market-localization",
    "t-affiliate-marketing",
    "t-brand-query"
   ],
   "short_answer":"Из-за условий задачи. Здесь высокая конкуренция и зрелые конкуренты, значит работать приходится точно, а не по чек-листу. Есть масштаб и несколько рынков, то есть технические и международные задачи, а не только правка метаданных. Часть рекламных каналов ограничена, поэтому у органики высокий вес и результат видно быстро. Мне интересна именно эта плотность обратной связи по данным. Про сам продукт скажу честно: я отношусь к нему как к регулируемой отрасли со своими правилами, и готов их соблюдать.",
