   "model_answer_full":"Сильный ответ не просто называет три слова, а показывает, что вы понимаете их независимость. Обход может не состояться из-за robots.txt, ошибки сервера или отсутствия ссылок. Индексация может не состояться из-за дублирования или недостаточной ценности — при полностью успешном обходе. Ранжирование существует только применительно к конкретному запросу, поэтому фраза «у страницы хорошие позиции» без указания запроса бессмысленна. Завершите практическим выводом: именно поэтому при проблеме сначала выясняют этап, а потом ищут причину.",
   "model_answer_short":"Три этапа. Crawling — робот находит URL по ссылкам или из sitemap и скачивает страницу. Indexing — Google разбирает содержимое, выбирает канонический URL и решает, хранить ли страницу. Ranking — под конкретный запрос из индекса подбираются лучшие ответы. Страница может быть обойдена, но не проиндексирована, и проиндексирована, но не ранжироваться — поэтому диагностику всегда веду по этапам.",
