   "model_answer_full":"Кроме самой разницы полезно показать понимание последствий. Неверно выбранный код приводит к тому, что в выдаче держится не тот адрес: при 302 на переехавшей странице старый URL остаётся каноническим. Упомяните цепочки редиректов как отдельную проблему: каждый лишний переход замедляет обход и загрузку. И назовите частую ошибку — массовый редирект удалённых страниц на главную, который трактуется как мягкая 404, потому что целевая страница не отвечает исходному запросу.",
   "model_answer_short":"301 — постоянное перенаправление: поисковик со временем заменит старый URL новым в индексе и перенесёт на него сигналы. 302 — временное: в индексе остаётся исходный URL. 301 ставят при переезде страницы, смене структуры или домена; 302 — на время работ или акции. Отдельно слежу, чтобы не образовывались цепочки: лучше вести на конечный URL одним переходом.",
