   "model_answer_full":"Ключевая мысль: формулировка запроса — только гипотеза, проверяется она выдачей. Добавьте, что смотреть нужно не только на тип страниц, но и на формат: если топ занят видео или картинками, текстовая страница будет системно проигрывать. Полезно упомянуть, что интент со временем меняется, поэтому выдачу стоит перепроверять, и что запросы с разным интентом нельзя объединять в один кластер — одна страница не закроет их одинаково хорошо.",
   "model_answer_short":"Интент — цель, с которой человек ввёл запрос: узнать, найти сайт, сравнить или совершить действие. Определяю по фактической выдаче: открываю её в инкогнито с нужным регионом и смотрю, какие типы страниц Google уже поставил в топ. Это его собственный ответ о том, какой интент он считает основным. Из этого следует тип страницы, которую нужно делать.",
