   "intent":"Проверка понимания разницы между ранжированием и кликабельностью",
   "model_answer_full":"Это вопрос на отсечение мифов, и правильный ответ короткий. Усилить его можно практикой: низкий CTR сам по себе не означает плохое описание — сначала смотрят позицию, потому что на пятнадцатом месте низкий CTR ожидаем. Также стоит сказать, что жёсткого лимита в символах не существует: важно, чтобы смысл читался в обрезанном виде на мобильном экране. И упомянуть, что одинаковые описания по всему сайту — признак шаблона без переменных.",
