   "intent":"Проверка системного troubleshooting и порядка действий",
   "model_answer_full":"Оценивается именно порядок, а не количество названных инструментов. Логика такая: если страница отдаёт не 200, все дальнейшие проверки бессмысленны, поэтому доступность идёт первой. Дальше — разрешения: robots.txt и директивы индексации. Затем канонизация: страница может быть исключена как дубль, и в проверке URL это видно по расхождению между указанным и выбранным каноническим адресом. Потом обнаружимость: есть ли внутренние ссылки, не является ли страница сиротой. И только в конце — рендеринг и содержательная ценность. Отдельно стоит различать статусы: «Обнаружена — не проиндексирована» значит, что обхода ещё не было, «Просканирована — не проиндексирована» — что обход состоялся, а в индекс URL не попал. Второй статус не называет причину, поэтому сильный ответ формулирует её как гипотезу и говорит, чем её проверить.",
   "model_answer_short":"Иду по порядку: код ответа, robots.txt, meta robots и X-Robots-Tag, canonical, внутренние ссылки и присутствие в sitemap, затем рендеринг и качество содержимого. Основной инструмент — проверка URL в Search Console: она показывает статус, выбранный Google канонический адрес и отрендеренный HTML. Сам статус диагнозом не считаю, причину проверяю гипотезами. На переобход отправляю после устранения причины; важный новый или сильно обновлённый URL отправляю сразу. Сроки индексации не обещаю.",
