   "model_answer_full":"Правильный ответ содержит и знание, и трезвость. Назовите метрики с порогами и обязательно разделите полевые данные CrUX и лабораторный прогон Lighthouse: расхождение между ними — обычная ситуация, и ориентироваться надо на полевые. Упомяните, что INP заменила прежнюю метрику FID — это показывает, что вы следите за изменениями. Про влияние говорите аккуратно: это часть оценки страницы, но обещать рост позиций от ускорения нельзя. Хорошее завершение — назвать типичные причины плохих значений: тяжёлые изображения первого экрана для LCP, длинные задачи в основном потоке для INP, элементы без заданных размеров для CLS.",
