   "model_answer_full":"Ценится не длина списка, а понимание границ каждого инструмента. Проговорите ключевое разделение: собственные данные (Search Console, аналитика) — факт, сторонние сервисы — модели на своей базе. Отсюда следует практическое правило: трафик и запросы своего сайта смотрю в Search Console, а Ahrefs использую там, где своих данных нет — по конкурентам. Хорошее дополнение — упомянуть связку инструментов: соединение выгрузки краулера с данными Search Console по URL позволяет приоритизировать технические правки по трафику.",
   "model_answer_short":"Search Console — фактические данные по своему сайту: запросы, показы, клики, индексация. GA4 — что происходит после перехода: посадочные страницы, вовлечённость, ключевые события. Screaming Frog — технический краул: коды ответа, дубли, редиректы. Ahrefs или Semrush — внешняя картина: конкуренты и незакрытые темы. Sheets — обработка выгрузок. По своему сайту доверяю Search Console, сторонние сервисы — это оценки.",
   "personal_evidence_prompt":"Перечислите инструменты, которыми вы действительно пользовались, и по одной задаче на каждый. Инструмент без задачи в этот список не попадает: на уточняющем вопросе это сразу видно.",
