   "intent":"Проверка практики работы с основным источником данных",
   "model_answer_full":"Сильный ответ показывает не список отчётов, а способ чтения. Основной приём в отчёте эффективности — разрезы и сравнение периодов: рост показов без роста кликов означает расширение охвата на дальних позициях, а не проблему сниппета. В отчёте индексирования важна динамика групп, а не абсолютные числа. Стоит упомянуть, что часть запросов скрыта из соображений приватности, поэтому сумма по запросам не сходится с итогом — это знание сразу отличает того, кто действительно работал с отчётом.",
   "model_answer_short":"Чаще всего отчёт эффективности: показы, клики, CTR и позицию в сравнении периодов, с разрезами по запросам и страницам. Отчёт об индексировании — чтобы видеть статусы исключений и их динамику. Инструмент проверки URL — для диагностики конкретной страницы. Отчёт по картам сайта — чтобы понимать, что из отправленного обработано.",
