   "intent":"Проверка практического навыка работы с данными",
   "model_answer_full":"Здесь ценят воспроизводимость. Ручная правка исходника — главный антипаттерн: через месяц никто не вспомнит, что и почему исправляли, и повторить обработку невозможно. Правильная схема: лист с сырыми данными, лист с нормализацией формулами, лист с результатом. Назовите конкретный практический сценарий — соединение выгрузки Screaming Frog с данными Search Console по URL, чтобы увидеть технические проблемы рядом с фактическими кликами. Это самый частый рабочий кейс и он сразу показывает опыт.",
   "model_answer_short":"Сначала привожу URL к одному виду, но нормализую только заведомо эквивалентное: протокол, www, завершающий слеш, регистр хоста, порядок параметров, трекинговые метки. Регистр пути и значимые параметры не трогаю — иначе склею разные страницы. Соединяю через XLOOKUP или ВПР, агрегирую сводными таблицами, для сложных выборок использую QUERY. Исходную выгрузку держу на отдельном листе и не правлю руками, чтобы обработку можно было повторить на новых данных.",
