   "intent":"Проверка умения формулировать задачу на контент",
   "model_answer_full":"Главное различие между слабым и сильным ТЗ — что в нём является предметом задачи. Слабое ТЗ описывает форму: количество знаков и плотность вхождений. Сильное описывает задачу: на какой вопрос текст должен ответить и для кого. Приведите конкретный контраст: вместо «вхождение аудит сайта пять раз» пишем «читатель не знает, что входит в аудит; ответить на четыре вопроса: что это, что входит, сколько занимает, что он получит на выходе». Объём указывайте ориентировочно и от задачи. Критерий приёмки должен быть проверяемым, иначе спор о качестве будет бесконечным.",
   "model_answer_short":"Указываю целевую страницу и основной запрос, объясняю интент и кто читатель, даю структуру по заголовкам и перечисляю обязательные смысловые блоки. Прикладываю две-три страницы из топа с пометкой, чем нужно быть полезнее. Ключевые слова передаю как смысл, а не как обязательные точные вхождения. Фиксирую проверяемые критерии приёмки.",
