   "intent":"Проверка навыка постановки задач смежной команде",
   "model_answer_full":"Хорошо работает, если вы приведёте пример прямо в ответе: «сейчас /catalog/item-1 отдаёт 302 на /shop/item-1, затем 301 на /shop/item-1/; нужно, чтобы отдавал сразу 301 на конечный URL; проверка — один переход, код 301; зачем — два перехода замедляют обход и размывают сигналы». Такой пример убедительнее любого описания подхода. Добавьте два принципа: не навязывать реализацию, потому что вы не знаете ограничений стека, и не помечать всё срочным, иначе приоритеты перестают работать. И обязательно про проверку после релиза — задачи, которые никто не проверил, регулярно возвращаются.",
   "model_answer_short":"Описываю текущее поведение и требуемое, обязательно с конкретными примерами URL. Формулирую через результат, а не через реализацию — как сделать, решает разработчик. Даю проверяемый критерий приёмки и одну фразу о том, зачем это бизнесу. Указываю приоритет. После выката проверяю сам и подтверждаю закрытие задачи.",
