   "model_answer_full":"Отчёт — это ответ на вопрос заказчика, а не демонстрация объёма работ. Начинайте с выводов, таблицы уносите в приложение. Обязательно разделяйте «сделано» и «дало результат»: в SEO между ними бывает несколько месяцев, и честное объяснение этого разрыва снимает много вопросов. Про метрики: клики и целевые действия важнее позиций, средняя позиция как главная метрика вводит в заблуждение, потому что ухудшается при появлении новых запросов. Про плохие новости: их включают в отчёт с объяснением причины — скрытая просадка всё равно всплывёт, но уже с потерей доверия.",
   "model_answer_short":"Тремя блоками: что сделано, что изменилось в цифрах, что планируется дальше. Цифры даю в сравнении периодов с учётом сезонности и отдельно поясняю, что уже дало эффект, а что ещё зреет. Данные Search Console и GA4 не смешиваю. Если есть просадка, показываю её и называю причину. Заканчиваю конкретным планом.",
