   "model_answer_full":"Ключевой элемент, который отличает сильный ответ, — способ проверки. Многие описывают, как читали документацию, но не говорят, как убедились, что поняли верно. Хорошие способы проверки: воспроизвести на тестовом примере, сверить с другим независимым источником, объяснить кому-то и увидеть, где объяснение разваливается. Второй важный элемент — иерархия источников: сначала официальная документация, потом практика, и только потом чужие статьи. Назовите срок: он показывает реальный темп обучения. И приведите результат — что вы в итоге смогли сделать, чего не могли до этого.",
   "model_answer_short":"Возьмите реальный случай, опишите, как искали информацию с приоритетом первоисточников, как проверяли правильность своего понимания на практике, и какой был результат с указанием срока.",
