   "intent":"Проверка поведения в условиях неопределённости",
   "model_answer_full":"Проверяется зрелость в работе с неопределённостью. Два антипаттерна: молча выбрать вариант, взяв на себя чужое решение, и попытаться сделать оба, сорвав сроки. Правильное поведение: зафиксировать противоречие явно, вынести его тому, кто может расставить приоритеты, предложить свой вариант с обоснованием и последствиями каждого выбора, получить решение и зафиксировать его письменно. Хорошее завершение — что вы изменили после: например, стали проговаривать границы задачи в начале, чтобы противоречия всплывали раньше. Жалоб на людей в ответе быть не должно, только описание ситуации.",
   "model_answer_short":"Опишите реальный случай: в чём именно было противоречие, как вы его обнаружили, с кем обсуждали, как договорились о приоритете, и что из этого получилось. Главное — показать, что вы не решали за всех молча и не пытались сделать всё сразу.",
