   "model_answer_full":"Задача — не безупречный английский, а связный короткий ответ. Три предложения достаточно: кто вы сейчас, что делали конкретно, чего хотите дальше. Простые конструкции надёжнее сложных. Профессиональные термины на английском вы и так знаете из документации — crawling, indexing, canonical, Search Console, — их использование звучит естественно. Если не хватает слова, лучше описать простыми словами, чем замолчать. Заучивать текст наизусть не стоит: при первом уточняющем вопросе это становится заметно. И отдельно: подставляйте свои факты. Выученная чужая биография разваливается на первом же «tell me more about that».",
   "model_answer_short":"Three sentences are enough: what you do now, what you did hands-on, what you want next. Keep the grammar simple — present perfect for the period, past simple for what you did, present simple for what you want. Use the terms you already read in the documentation: crawling, indexing, canonical, Search Console. Put your own facts in: this frame is a structure, not an answer.",
