   "intent":"Проверка профессионального объяснения на английском",
   "model_answer_full":"Этот вопрос удобен тем, что термины и так английские, поэтому нужны только простые связки. Структура: определение первого понятия, определение второго, практическое следствие. Полезные конструкции: «Crawling is when...», «Indexing happens after...», «This means that...». Обязательно добавьте следствие — именно оно показывает понимание, а не заучивание. Если формулировка даётся тяжело, замедлите темп: короткие простые предложения воспринимаются лучше, чем попытка построить сложную конструкцию и запутаться в середине.",
   "model_answer_short":"Crawling is when the search engine bot discovers a URL and downloads the page. Indexing is when Google analyses that page, picks a canonical URL, and decides whether to store it. Crawling does not guarantee indexing: a page can be crawled and still not be indexed, usually because of duplication or low value.",
