   "model_answer_full":"Сильный ответ содержит не только три задачи, но и практические маркеры: страницы-сироты, на которые не ведёт ни одна внутренняя ссылка, глубина клика от главной, и разница между ссылками в основном контенте и в сквозном подвале. Упомяните частую ошибку — анкоры «здесь» и «подробнее», которые не сообщают ничего ни человеку, ни поисковику. И отдельно скажите, что nofollow на внутренних ссылках практически никогда не нужен: попытка перераспределить вес таким способом обычно просто лишает целевую страницу сигнала.",
