   "intent":"Проверка понимания связи между метриками и бизнес-результатом",
   "model_answer_full":"Ответ проверяет способность связать SEO с деньгами. Постройте цепочку: видимость (показы) — переходы (клики) — поведение (посадочные страницы, вовлечённость) — результат (ключевые события). На каждом уровне свой источник данных, и смешивать их числа нельзя: клики Search Console не равны сессиям GA4 по объективным причинам. Два обязательных уточнения, которые показывают зрелость: отделение брендового трафика, который растёт от рекламы и известности, и учёт сезонности через сравнение с аналогичным периодом прошлого года. Если ключевые события не настроены, честно скажите, что первым делом настроили бы их — без этого оценка SEO остаётся разговором о трафике.",
   "model_answer_short":"Смотрю два источника вместе. Search Console — показы, клики и запросы: это видимость. GA4 — канал Organic Search: посадочные страницы, вовлечённость, ключевые события. Отдельно отделяю брендовый трафик, чтобы не приписывать себе рост от рекламы. Сравниваю периоды с учётом сезонности. Итоговый критерий — целевые действия из органики, а не общий трафик и не позиции.",
