   "model_answer_full":"Ключевая развилка в этом кейсе — отличить проблему шаблона от проблемы дублей. Если страницы действительно про разное, решение масштабируемое: формула шаблона с переменными, которую разработчик применит ко всем страницам сразу. Если содержимое тоже одинаковое, правка заголовков ничего не даст — там нужно решать вопрос дублей через canonical или объединение. Ручная правка сотен страниц — антипаттерн: она не воспроизводима и не переживает следующий релиз. Добавьте про приоритизацию: сначала страницы, которые уже дают показы, — там эффект виден быстрее всего. И про проверку: после выката выборочно смотрю страницы каждого типа и слежу за динамикой CTR.",
