   "model_answer_full":"Главная ошибка — одно правило Disallow на все параметры. Оно закроет и нужные страницы фильтров, а уже проиндексированные адреса из индекса не уберёт. Правильный порядок: классификация по назначению, потом решение под каждый класс. Отдельно проговорите критерий для фасетных страниц: открываем только те комбинации, под которые есть подтверждённый спрос и подготовленное содержимое, обычно одно-двухпризнаковые. Про измерение: на крупных сайтах доля обхода, уходящая на параметрические URL, видна в логах — это и есть аргумент для разработки. И про внедрение: изменения такого масштаба выкатывают поэтапно, наблюдая за динамикой групп в отчёте индексирования, чтобы вовремя откатиться.",
   "model_answer_short":"Сначала классифицирую параметры: сортировка, пагинация, фильтры, метки отслеживания. Сортировки и метки закрываю canonical на базовую страницу. По фильтрам смотрю спрос: комбинации с реальным спросом и подготовленным содержимым оставляю открытыми, остальные — noindex и ограничение обхода. Влияние оцениваю по логам и отчёту индексирования. Внедряю постепенно, чтобы видеть эффект.",
