   "model_answer_short":"Сначала проверяю сам разрыв: сравниваю по ссылающимся доменам, а не по числу ссылок, и смотрю, на какие страницы конкурента они ведут. Часто выясняется, что отставание не по домену в целом, а по конкретным посадочным страницам, и это уже другая задача. Дальше строю отчёт по ссылочному разрыву и фильтрую по теме, живому трафику и достижимости — из сотен доменов остаются десятки. План: аутрич по отобранным площадкам плюс один-два повода для digital PR. Про закупку говорю прямо: это описано в спам-политиках как ссылочная схема, такие ссылки чаще всего просто не учитываются, а при масштабе можно получить ручные меры. Метрику оговариваю заранее: прирост доноров на целевые страницы и динамика видимости, а не число размещений.",
