   "model_answer_full":"Вопрос задают всем и слушают не содержание, а тон. Провальные варианты два: изобразить страсть к азартным играм и начать оправдываться за отрасль. Оба читаются как неготовность к разговору. Рабочая рамка — профессиональные условия задачи: конкуренция, при которой работать приходится точно, а не по чек-листу; масштаб и несколько рынков, то есть технические и международные задачи; ограничения рекламных каналов, из-за которых у органики высокий вес и результат виден внутри компании. Полезно добавить одну конкретную деталь, которую вы сами заметили в выдаче ниши: например, что коммерческие запросы отдают партнёрские рейтинги, а не сайты операторов. Про сам продукт достаточно одной взрослой фразы: это регулируемая отрасль со своими правилами, и вы готовы их соблюдать.",
   "model_answer_short":"Каркас из трёх частей. Первая — что в условиях задачи профессионально интересно: высокая конкуренция и зрелые конкуренты, масштаб, несколько рынков, а значит технические и международные задачи, а не только правка метаданных. Вторая — почему здесь быстрее растёшь: часть рекламных каналов ограничена, вес органики выше, обратная связь по данным приходит быстро. Третья — спокойное отношение к отрасли: регулируемая ниша со своими правилами, готов их соблюдать. Свою причину подставляете свою — заученный чужой ответ на уточняющем вопросе слышно сразу.",
