   "model_answer_full":"Задание проверяет две вещи сразу: понимаете ли вы механизм и умеете ли объяснить его без жаргона на английском. Используйте каркас ANSWER — REASON — EXAMPLE — CHECK. Ответ одной фразой: контроль обхода. Причина: обход и индексация — разные вещи, и именно на этом чаще всего ошибаются. Пример: сравнение с табличкой на двери, понятное человеку без SEO-контекста. Проверка: назвать инструмент, которым вы убедитесь в результате. Грамматика нужна простая — present simple и модальные глаголы. Полезные конструкции: «it controls…», «it does not guarantee…», «the way to do that is…», «I would check it with…». Если менеджер спросит «so how do we remove the page», ответ должен быть готов: noindex, or a 404, or password protection, depending on what should happen to the page.",
   "model_answer_short":"robots.txt tells search engine crawlers which parts of the site they should not request. It controls crawling, not indexing: if a page is blocked but other sites link to it, Google may still show the URL in the results, usually without a description. To keep a page out of the results, we let the crawler in and add a noindex tag instead. A simple comparison: robots.txt is a sign on the door saying please do not come in, while noindex is a note asking not to publish what you found. I would check the file itself and then use the URL Inspection tool in Search Console to see what Google actually does with the URL.",
